#include "awt/geom/jxx.awt.geom.Ellipse2D.h"
#include <algorithm>
#include "awt/geom/jxx.awt.geom.Point2D.h"
#include "awt/geom/jxx.awt.geom.Rectangle2D.h"
namespace jxx::awt::geom { ::jxx::lang::jbool Ellipse2D::contains(::jxx::lang::jdouble px,::jxx::lang::jdouble py)const{if(isEmpty())return false;auto nx=(px-getX())/getWidth()-0.5,ny=(py-getY())/getHeight()-0.5;return nx*nx+ny*ny<0.25;} ::jxx::lang::jbool Ellipse2D::contains(const ::jxx::Ptr<Point2D>&p)const{return p&&contains(p->getX(),p->getY());} ::jxx::lang::jbool Ellipse2D::intersects(::jxx::lang::jdouble x,::jxx::lang::jdouble y,::jxx::lang::jdouble w,::jxx::lang::jdouble h)const{if(w<=0||h<=0||isEmpty())return false;auto cx=std::max(x,std::min(getCenterX(),x+w)),cy=std::max(y,std::min(getCenterY(),y+h));return contains(cx,cy);} ::jxx::lang::jbool Ellipse2D::intersects(const ::jxx::Ptr<Rectangle2D>&r)const{return r&&intersects(r->getX(),r->getY(),r->getWidth(),r->getHeight());} ::jxx::lang::jbool Ellipse2D::contains(::jxx::lang::jdouble x,::jxx::lang::jdouble y,::jxx::lang::jdouble w,::jxx::lang::jdouble h)const{return w>=0&&h>=0&&contains(x,y)&&contains(x+w,y)&&contains(x,y+h)&&contains(x+w,y+h);} ::jxx::lang::jbool Ellipse2D::contains(const ::jxx::Ptr<Rectangle2D>&r)const{return r&&contains(r->getX(),r->getY(),r->getWidth(),r->getHeight());} ::jxx::Ptr<Rectangle2D> Ellipse2D::getBounds2D()const{return ::jxx::NEW<Rectangle2D::Double>(getX(),getY(),getWidth(),getHeight());} }
